// Run parameters for MYIMAGE-1262. write:true = writes enabled.
const P = { project_id: '3070657967b5854be32cb1.65162854', tags: ['MYIMAGE-1262', 'MYIMAGE-1271'], feature_tag: 'checkout-compliance', attachments: ['76229'], screenshot: { att_id: '76229', title: 'MYIMAGE-1262 – Checkout, US legal note (trial)', description: 'Checkout page (/checkout) for US visitors, staging, from MYIMAGE-1255 (QA pass, 12 Nov 2026). The legal note under the Get Image button: the renewal period appears after "every" (here "every 4 weeks"). The no-trial version of the note also shows the plan name ("the Monthly Plan"). Shot taken before the MYIMAGE-1262 fix; the English text is unchanged.' }, write: true };
const KEYS = { 979794031: ['plan_name', 'days'], 979794032: ['plan_name', 'weeks'], 979794033: ['plan_name', 'months'], 979794034: ['plan_name', 'years'], 979794035: ['renewal_period', 'days'], 979794036: ['renewal_period', 'weeks'], 979794037: ['renewal_period', 'months'], 979794038: ['renewal_period', 'years'] };
const U = { days: ['day', 'Daily', 'Day', 7], weeks: ['week', 'Weekly', 'Week', 4], months: ['month', 'Monthly', 'Month', 3], years: ['year', 'Yearly', 'Year', 2] };
const T = ' Ticket: MYIMAGE-1262 (fix of MYIMAGE-1255).';
const d = {};
for (const id of Object.keys(KEYS)) {
  const kind = KEYS[id][0]; const unit = KEYS[id][1]; const u = U[unit];
  if (kind === 'renewal_period') {
    d[id] = 'Checkout page (/checkout), US visitors only: the renewal period inserted into the legal note under the payment form, right after the word "every" in pages::checkout::agree_description_us and pages::checkout::agree_description_us_no_trial ("...will automatically renew at {subscriptionPrice} every {renewalPeriod} until you cancel."). Noun (a length of time), not a verb. Plural key, unit = ' + unit + ': count = the plan\'s billing interval; "one" = an interval of exactly 1, shown with no number ("every ' + u[0] + '"); "other" = "every ' + u[3] + ' ' + unit + '". Keep #; if your language\'s "one" form also covers numbers like 21 or 31, keep # in that form too. Translate it so it fits right after your translation of "every" in those two sentences (same case). If "every" must change between 1 and several in your language (e.g. FR chaque mois / tous les 3 mois, DE jeden Monat / alle 3 Monate), leave a comment on the key: "every" sits in the parent sentence. US auto-renewal legal disclosure: translate exactly, don\'t shorten.' + T;
  } else {
    d[id] = 'Checkout page (/checkout), US visitors only: name of the subscription plan inserted into the legal note under the payment form, in pages::checkout::agree_description_us_no_trial ("...you agree to be charged {subscriptionPrice} today for the {planName} Plan.") -> "the ' + u[1] + ' Plan" / "the ' + u[3] + '-' + u[2] + ' Plan". Adjective/modifier describing "Plan" (the noun "Plan" and "the" are in the parent sentence), not a noun on its own and not a verb. Plural key, unit = ' + unit + ': count = the plan\'s billing interval; "one" = "' + u[1] + '" (billed every ' + u[0] + ', no number); "other" = "#-' + u[2] + '" (e.g. ' + u[3] + '-' + u[2] + ' = billed every ' + u[3] + ' ' + unit + '). Keep #. Capitalised in English because it is a plan name; use your language\'s usual capitalisation for plan names. It has to agree with your translation of "Plan" in that sentence (gender, number, case, word order); if that is not possible with the noun outside this key, leave a comment on the key. US auto-renewal legal disclosure.' + T;
  }
}
P.key_ids = Object.keys(KEYS).map(Number); P.descriptions = d;
return [{ json: P }];

const atts = $('Att List').all(); const items = $input.all(); const out = [];
for (let i = 0; i < items.length; i++) {
  const b = items[i].binary && items[i].binary.data;
  const id = atts[i] ? atts[i].json.att_id : String(i);
  if (!b) { out.push({ json: { att_id: id, ok: false, err: JSON.stringify(items[i].json).slice(0, 300) } }); continue; }
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  out.push({ json: { att_id: id, ok: true, mime: b.mimeType, size: buf.length, b64: buf.toString('base64') } });
}
return out;

const p = $('Params').first().json;
const keys = (($('Get Keys').first().json.body || {}).keys) || [];
const tagged = (($('Get 1255 Keys').first().json.body || {}).keys) || [];
const tagUnion = {}; for (const k of tagged) { for (const t of (k.tags || [])) { tagUnion[t] = (tagUnion[t] || 0) + 1; } }
const want = p.tags.concat(p.feature_tag ? [p.feature_tag] : []);
const updates = []; const state = [];
for (const k of keys) {
  if (k.is_archived) { continue; }
  const u = { key_id: k.key_id }; let any = false;
  const add = want.filter(function (t) { return (k.tags || []).indexOf(t) < 0; });
  if (add.length) { u.tags = add; u.merge_tags = true; any = true; }
  const d = p.descriptions[String(k.key_id)];
  if (d && !(k.description || '').trim()) { u.description = d; any = true; }
  if (any) { updates.push(u); }
  state.push({ key_id: k.key_id, name: k.key_name && k.key_name.web, tags: k.tags, desc_len: (k.description || '').length, screenshots: (k.screenshots || []).length });
}
let shot = null;
if (p.screenshot) {
  const img = $('Images').all().map(function (x) { return x.json; }).filter(function (x) { return x.att_id === p.screenshot.att_id && x.ok; })[0];
  const ids = keys.filter(function (k) { return (k.screenshots || []).length === 0; }).map(function (k) { return k.key_id; });
  if (img && ids.length) { shot = { screenshots: [{ data: 'data:' + img.mime + ';base64,' + img.b64, title: p.screenshot.title, description: p.screenshot.description, ocr: false, key_ids: ids, tags: ['MYIMAGE-1262'] }] }; }
}
const images = p.write ? [] : $('Images').all().map(function (x) { return x.json; });
return [{ json: { write: p.write, project_id: p.project_id, state: state, tag_union_1255: tagUnion, updates: updates,
  first: { keys: updates.slice(0, 1) }, rest: { keys: updates.slice(1) }, has_rest: updates.length > 1, has_first: updates.length > 0,
  shot: shot, images: images } }];

const p = $('Params').first().json;
const keys = (($('Read Back').first().json.body || {}).keys) || [];
const want = p.tags.concat(p.feature_tag ? [p.feature_tag] : []);
const before = {}; for (const s of $('Build').first().json.state) { before[s.key_id] = s; }
const rows = keys.map(function (k) { const b = before[k.key_id] || { tags: [] };
  return { key_id: k.key_id, name: k.key_name && k.key_name.web, tags: k.tags, has_new_tags: want.every(function (t) { return (k.tags || []).indexOf(t) >= 0; }),
    kept_old_tags: (b.tags || []).every(function (t) { return (k.tags || []).indexOf(t) >= 0; }), desc_ok: !!(k.description || '').trim(), screenshots: (k.screenshots || []).length }; });
const r1 = $('PUT First').first().json; const r2 = $('PUT Rest').first().json; const r3 = $('POST Screenshot').first().json;
return [{ json: { put_first: r1.statusCode, put_rest: r2.statusCode, put_errors: [(r1.body || {}).errors, (r2.body || {}).errors], shot_status: r3.statusCode, shot_body: JSON.stringify(r3.body || {}).slice(0, 600), rows: rows } }];
